import { useState, useEffect, useCallback, useMemo, useRef } from "react";

const DEFAULT_TEAMS = Array.from({ length: 10 }, (_, i) => `Team ${i + 1}`);

// The National Golf Brussels - exact brand colors
const C = {
  // Primary greens (from logo image: #13241a)
  greenDeep: "#13241a",
  greenDark: "#1a2f22",
  greenMid: "#223d2c",
  greenLight: "#2d4f38",
  greenAccent: "#3a6648",
  greenSoft: "#4a7a58",
  // Cream / off-white text (from logo: near #fcfffd)
  cream: "#f0ebe0",
  creamLight: "#f7f4ed",
  creamBright: "#fcfaf5",
  // Muted tones
  sage: "#8a9e8e",
  sageDark: "#6b8370",
  sageMuted: "#556b5a",
  // Functional
  correct: "#5a9e6a",
  correctBright: "#6ab87a",
  wrong: "#c45c5c",
  wrongBright: "#d46a6a",
  // Answer reference
  answerBg: "#f5f0e0",
  answerText: "#7a6830",
  // Podium
  gold: "#d4af37",
  goldLight: "#e0c45c",
  silver: "#b0b0b0",
  bronze: "#b87333",
  // Borders & overlays
  border: "rgba(240, 235, 224, 0.12)",
  borderMed: "rgba(240, 235, 224, 0.20)",
  borderLight: "rgba(240, 235, 224, 0.06)",
  overlay: "rgba(19, 36, 26, 0.93)",
};

const HERO_BG = "https://www.thenationalgolf.be/assets/uploads/site/HE4A6957-HDR-bewerkt.jpg";



const LOGO_DATA_URI = "data:image/svg+xml;base64,";

const LogoMark = ({ size = "md" }) => {
  const widths = { sm: 100, md: 160, lg: 220 };
  return (
    <div style={ { display: "flex", flexDirection: "column", alignItems: "center" } }>
      <img src={LOGO_DATA_URI} alt="The National Golf Brussels" style={ { width: widths[size], height: "auto" } } />
    </div>
  );
};

const SESSION_KEY = "gq-session-code";

function App() {
  const [roundsData, setRoundsData] = useState(null);
  const [roundOrder, setRoundOrder] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const [sessionCode, setSessionCode] = useState(null);
  const [view, setView] = useState("lobby");
  const [teams, setTeams] = useState(DEFAULT_TEAMS);
  const [teamCount, setTeamCount] = useState(10);
  const [scores, setScores] = useState({});
  const [activeRound, setActiveRound] = useState(null);
  const [showAnswers, setShowAnswers] = useState(true);
  const [revealCount, setRevealCount] = useState(0);
  const [revealed, setRevealed] = useState(false);

  const initialized = useRef(false);
  const saveTimer = useRef(null);

  const restoreSession = useCallback((session, quizRoundOrder) => {
    setSessionCode(session.id);
    localStorage.setItem(SESSION_KEY, session.id);
    setTeams(session.teams || DEFAULT_TEAMS);
    setTeamCount(session.teamCount || 10);
    setScores(session.scores || {});
    setActiveRound(session.activeRound || quizRoundOrder[0]);
    setView(session.view === "lobby" ? "setup" : (session.view || "setup"));
    setShowAnswers(session.showAnswers !== undefined ? session.showAnswers : true);
  }, []);

  // Load quiz data + try to resume session from localStorage
  useEffect(() => {
    const savedCode = localStorage.getItem(SESSION_KEY);

    const quizPromise = fetch("/api/quiz-data").then(r => {
      if (!r.ok) throw new Error(`Failed to load quiz data (${r.status})`);
      return r.json();
    });

    const sessionPromise = savedCode
      ? fetch(`/api/session/${savedCode}`).then(r => r.ok ? r.json().then(d => d.session) : null)
      : Promise.resolve(null);

    Promise.all([quizPromise, sessionPromise])
      .then(([quizData, session]) => {
        setRoundsData(quizData.rounds);
        setRoundOrder(quizData.roundOrder);
        if (session) {
          restoreSession(session, quizData.roundOrder);
        } else {
          localStorage.removeItem(SESSION_KEY);
          setActiveRound(quizData.roundOrder[0]);
          setView("lobby");
        }
        setLoading(false);
        initialized.current = true;
      })
      .catch(err => {
        setError(err.message);
        setLoading(false);
      });
  }, [restoreSession]);

  // Auto-save session to Cosmos DB (debounced 500ms)
  useEffect(() => {
    if (!initialized.current || !sessionCode || view === "lobby") return;
    if (saveTimer.current) clearTimeout(saveTimer.current);
    saveTimer.current = setTimeout(() => {
      fetch(`/api/session/${sessionCode}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ teams, teamCount, scores, activeRound, view, showAnswers }),
      }).catch(() => {});
    }, 500);
    return () => { if (saveTimer.current) clearTimeout(saveTimer.current); };
  }, [teams, teamCount, scores, activeRound, view, showAnswers, sessionCode]);

  const handleNewSession = useCallback(() => {
    return fetch("/api/session", { method: "POST" })
      .then(r => { if (!r.ok) throw new Error("Failed to create session"); return r.json(); })
      .then(d => {
        restoreSession(d.session, roundOrder);
        setView("setup");
        initialized.current = true;
      });
  }, [roundOrder, restoreSession]);

  const handleJoinSession = useCallback((code) => {
    return fetch(`/api/session/${code}`)
      .then(r => { if (!r.ok) throw new Error("Session not found"); return r.json(); })
      .then(d => {
        restoreSession(d.session, roundOrder);
        initialized.current = true;
      });
  }, [roundOrder, restoreSession]);

  const handleLeaveSession = useCallback(() => {
    localStorage.removeItem(SESSION_KEY);
    setSessionCode(null);
    setView("lobby");
    setTeams([...DEFAULT_TEAMS]);
    setTeamCount(10);
    setScores({});
    setActiveRound(roundOrder[0] || null);
    setShowAnswers(true);
    setRevealCount(0);
    setRevealed(false);
    initialized.current = false;
  }, [roundOrder]);

  const activeTeams = useMemo(() => teams.slice(0, teamCount), [teams, teamCount]);

  const setScore = useCallback((teamIdx, questionId, value) => {
    setScores(prev => {
      const key = `${teamIdx}-${questionId}`;
      const n = { ...prev };
      if (prev[key] === value) delete n[key]; else n[key] = value;
      return n;
    });
  }, []);

  const getTeamRoundScore = useCallback((teamIdx, roundId) => {
    if (!roundsData?.[roundId]) return 0;
    return roundsData[roundId].questions.reduce((sum, q) => sum + (scores[`${teamIdx}-${q.id}`] === 1 ? 1 : 0), 0);
  }, [scores, roundsData]);

  const getTeamTotal = useCallback((teamIdx) => {
    return roundOrder.reduce((sum, rid) => sum + getTeamRoundScore(teamIdx, rid), 0);
  }, [getTeamRoundScore, roundOrder]);

  const leaderboard = useMemo(() => {
    const data = activeTeams.map((name, idx) => ({
      name, idx, total: getTeamTotal(idx),
      rounds: roundOrder.reduce((a, rid) => { a[rid] = getTeamRoundScore(idx, rid); return a; }, {}),
    }));
    data.sort((a, b) => b.total - a.total || a.name.localeCompare(b.name));
    let rank = 1;
    data.forEach((item, i) => { if (i > 0 && item.total < data[i - 1].total) rank = i + 1; item.rank = rank; });
    return data;
  }, [activeTeams, getTeamTotal, getTeamRoundScore, roundOrder]);

  if (loading) return (
    <div style={{ minHeight: "100vh", background: C.greenDeep, display: "flex", alignItems: "center", justifyContent: "center" }}>
      <div style={{ textAlign: "center" }}>
        <LogoMark size="lg" />
        <div style={{ marginTop: 24, color: C.sage, fontFamily: "'Inter', sans-serif", fontSize: 14 }}>Loading...</div>
      </div>
    </div>
  );

  if (error) return (
    <div style={{ minHeight: "100vh", background: C.greenDeep, display: "flex", alignItems: "center", justifyContent: "center" }}>
      <div style={{ textAlign: "center", maxWidth: 400, padding: 20 }}>
        <LogoMark size="lg" />
        <div style={{ marginTop: 24, color: C.wrong, fontFamily: "'Inter', sans-serif", fontSize: 14 }}>{error}</div>
        <button onClick={() => window.location.reload()} style={{ ...btnPrimary, marginTop: 16 }}>Retry</button>
      </div>
    </div>
  );

  if (view === "lobby") return <LobbyView onNewSession={handleNewSession} onJoinSession={handleJoinSession} />;
  if (view === "setup") return <SetupView teams={teams} setTeams={setTeams} teamCount={teamCount} setTeamCount={setTeamCount} onStart={() => setView("scoring")} onLeaveSession={handleLeaveSession} sessionCode={sessionCode} />;
  if (view === "leaderboard") return <LeaderboardView leaderboard={leaderboard} onBack={() => setView("scoring")} revealed={revealed} setRevealed={setRevealed} revealCount={revealCount} setRevealCount={setRevealCount} roundsData={roundsData} roundOrder={roundOrder} sessionCode={sessionCode} />;
  return (
    <ScoringView
      activeRound={activeRound} setActiveRound={setActiveRound} activeTeams={activeTeams}
      scores={scores} setScore={setScore} getTeamRoundScore={getTeamRoundScore}
      showAnswers={showAnswers} setShowAnswers={setShowAnswers}
      onLeaderboard={() => { setRevealed(false); setRevealCount(0); setView("leaderboard"); }}
      onSetup={() => setView("setup")}
      roundsData={roundsData} roundOrder={roundOrder} sessionCode={sessionCode}
    />
  );
}

function LobbyView({ onNewSession, onJoinSession }) {
  const [joinCode, setJoinCode] = useState("");
  const [busy, setBusy] = useState(false);
  const [joinError, setJoinError] = useState(null);

  const handleNew = () => {
    setBusy(true);
    onNewSession().catch(() => setBusy(false));
  };

  const handleJoin = () => {
    const code = joinCode.trim().toUpperCase();
    if (!code) return;
    setBusy(true);
    setJoinError(null);
    onJoinSession(code).catch(() => {
      setJoinError("Session not found. Check the code and try again.");
      setBusy(false);
    });
  };

  return (
    <div style={{ minHeight: "100vh", background: `url(${HERO_BG}) center/cover no-repeat fixed`, display: "flex", alignItems: "center", justifyContent: "center", padding: 20 }}>
      <div style={{ position: "fixed", inset: 0, background: C.overlay, zIndex: 0 }} />
      <div style={{ position: "relative", zIndex: 1, maxWidth: 400, width: "100%" }}>
        <div style={{ textAlign: "center", marginBottom: 32 }}>
          <LogoMark size="lg" />
          <div style={{ marginTop: 24, fontFamily: "'Inter', sans-serif", fontSize: 12, letterSpacing: 5, textTransform: "uppercase", color: C.sage, fontWeight: 300 }}>
            Quiz Session
          </div>
        </div>

        <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
          <div style={{ background: C.greenDark, borderRadius: 4, padding: "24px", border: `1px solid ${C.border}`, boxShadow: "0 20px 60px rgba(0,0,0,0.4)" }}>
            <div style={{ fontSize: 13, color: C.sage, marginBottom: 14, fontFamily: "'Inter', sans-serif" }}>Start fresh with a new session code</div>
            <button onClick={handleNew} disabled={busy} style={{ ...btnPrimary, width: "100%", opacity: busy ? 0.6 : 1 }}>
              {busy ? "Creating..." : "New Quiz Session"}
            </button>
          </div>

          <div style={{ textAlign: "center", fontSize: 11, color: C.sageDark, fontFamily: "'Inter', sans-serif", letterSpacing: 2, textTransform: "uppercase" }}>or</div>

          <div style={{ background: C.greenDark, borderRadius: 4, padding: "24px", border: `1px solid ${C.border}`, boxShadow: "0 20px 60px rgba(0,0,0,0.4)" }}>
            <div style={{ fontSize: 13, color: C.sage, marginBottom: 14, fontFamily: "'Inter', sans-serif" }}>Join an existing session</div>
            <div style={{ display: "flex", gap: 8 }}>
              <input
                value={joinCode} placeholder="e.g. GQ-7K3M"
                onChange={e => { setJoinCode(e.target.value.toUpperCase()); setJoinError(null); }}
                onKeyDown={e => e.key === "Enter" && handleJoin()}
                style={{ flex: 1, padding: "10px 14px", border: `1px solid ${C.border}`, borderRadius: 3, fontSize: 15, background: C.greenDeep, color: C.cream, outline: "none", fontFamily: "'Inter', sans-serif", letterSpacing: 2, textAlign: "center" }}
                onFocus={e => e.target.style.borderColor = C.greenSoft}
                onBlur={e => e.target.style.borderColor = C.border}
              />
              <button onClick={handleJoin} disabled={busy || !joinCode.trim()} style={{ ...btnPrimary, opacity: (busy || !joinCode.trim()) ? 0.6 : 1, padding: "10px 20px" }}>Join</button>
            </div>
            {joinError && <div style={{ marginTop: 10, fontSize: 12, color: C.wrong, fontFamily: "'Inter', sans-serif" }}>{joinError}</div>}
          </div>
        </div>
      </div>
    </div>
  );
}

function SessionBadge({ code }) {
  return (
    <span style={{ display: "inline-block", padding: "3px 10px", background: C.greenMid, borderRadius: 3, fontSize: 11, fontWeight: 600, letterSpacing: 2, color: C.sage, fontFamily: "'Inter', sans-serif", border: `1px solid ${C.border}` }}>
      {code}
    </span>
  );
}

function SetupView({ teams, setTeams, teamCount, setTeamCount, onStart, onLeaveSession, sessionCode }) {
  return (
    <div style={{ minHeight: "100vh", background: `url(${HERO_BG}) center/cover no-repeat fixed`, display: "flex", alignItems: "center", justifyContent: "center", padding: 20 }}>
      <div style={{ position: "fixed", inset: 0, background: C.overlay, zIndex: 0 }} />
      <div style={{ position: "relative", zIndex: 1, maxWidth: 440, width: "100%" }}>
        <div style={{ textAlign: "center", marginBottom: 32 }}>
          <LogoMark size="lg" />
          <div style={{ marginTop: 16 }}><SessionBadge code={sessionCode} /></div>
          <div style={{ marginTop: 12, fontFamily: "'Inter', sans-serif", fontSize: 12, letterSpacing: 5, textTransform: "uppercase", color: C.sage, fontWeight: 300 }}>
            Quiz Session
          </div>
        </div>

        <div style={{ background: C.greenDark, borderRadius: 4, padding: "28px 24px", border: `1px solid ${C.border}`, boxShadow: "0 20px 60px rgba(0,0,0,0.4)" }}>
          <div style={{ marginBottom: 20 }}>
            <label style={labelStyle}>Number of teams: <span style={{ color: C.cream, fontWeight: 500 }}>{teamCount}</span></label>
            <input type="range" min={2} max={20} value={teamCount} onChange={e => setTeamCount(Number(e.target.value))}
              style={{ width: "100%", accentColor: C.greenSoft, marginTop: 6 }} />
            <div style={{ display: "flex", justifyContent: "space-between", fontSize: 10, color: C.sageDark, marginTop: 2 }}><span>2</span><span>20</span></div>
          </div>

          <div style={{ marginBottom: 24 }}>
            <label style={labelStyle}>Team names</label>
            <div style={{ maxHeight: 280, overflowY: "auto", display: "flex", flexDirection: "column", gap: 4, marginTop: 8, paddingRight: 4 }}>
              {Array.from({ length: teamCount }, (_, i) => (
                <div key={i} style={{ display: "flex", alignItems: "center", gap: 8 }}>
                  <span style={{ width: 22, textAlign: "right", fontSize: 11, color: C.sageDark, fontWeight: 500, flexShrink: 0 }}>{i + 1}</span>
                  <input
                    value={teams[i] || ""} placeholder={`Team ${i + 1}`}
                    onChange={e => { const n = [...teams]; while (n.length <= i) n.push(""); n[i] = e.target.value; setTeams(n); }}
                    style={{ flex: 1, padding: "9px 12px", border: `1px solid ${C.border}`, borderRadius: 3, fontSize: 13, background: C.greenDeep, color: C.cream, outline: "none", fontFamily: "'Inter', sans-serif" }}
                    onFocus={e => e.target.style.borderColor = C.greenSoft}
                    onBlur={e => e.target.style.borderColor = C.border}
                  />
                </div>
              ))}
            </div>
          </div>

          <button onClick={onStart} style={{ ...btnPrimary, width: "100%" }}>Start Scoring</button>
          <button onClick={onLeaveSession} style={{ ...btnGhost, width: "100%", marginTop: 10, fontSize: 12 }}>New Quiz Session</button>
        </div>
      </div>
    </div>
  );
}

function ScoringView({ activeRound, setActiveRound, activeTeams, scores, setScore, getTeamRoundScore, showAnswers, setShowAnswers, onLeaderboard, onSetup, roundsData, roundOrder, sessionCode }) {
  const round = roundsData[activeRound];
  return (
    <div style={{ minHeight: "100vh", background: C.greenDeep, fontFamily: "'Inter', 'Helvetica Neue', sans-serif" }}>
      {/* Top bar */}
      <div style={{ background: C.greenDark, padding: "8px 16px", display: "flex", alignItems: "center", justifyContent: "space-between", position: "sticky", top: 0, zIndex: 100, borderBottom: `1px solid ${C.border}` }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <LogoMark size="sm" />
          <SessionBadge code={sessionCode} />
        </div>
        <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
          <button onClick={onSetup} style={btnGhost}>Setup</button>
          <button onClick={onLeaderboard} style={btnAccent}>Leaderboard</button>
        </div>
      </div>

      {/* Round tabs */}
      <div style={{ padding: "10px 12px 8px", overflowX: "auto", whiteSpace: "nowrap", background: C.greenDeep, borderBottom: `1px solid ${C.borderLight}` }}>
        <div style={{ display: "inline-flex", gap: 4 }}>
          {roundOrder.map(rid => {
            const r = roundsData[rid];
            const isActive = rid === activeRound;
            const lbl = r.type === "series" ? `S${rid.slice(-1)}` : r.type === "varia" ? "Varia" : "Photo";
            return (
              <button key={rid} onClick={() => setActiveRound(rid)} style={{
                padding: "6px 14px", borderRadius: 3, cursor: "pointer", fontSize: 11, fontWeight: isActive ? 600 : 400,
                letterSpacing: 1.5, textTransform: "uppercase", transition: "all 0.15s",
                background: isActive ? C.cream : "transparent", color: isActive ? C.greenDeep : C.sage,
                border: isActive ? "none" : `1px solid ${C.borderLight}`,
                fontFamily: "'Inter', sans-serif",
              }}>{lbl}</button>
            );
          })}
        </div>
      </div>

      {/* Round header */}
      <div style={{ padding: "16px 16px 10px", display: "flex", alignItems: "center", justifyContent: "space-between" }}>
        <div>
          <h2 style={{ margin: 0, fontSize: 18, fontWeight: 300, color: C.cream, letterSpacing: 3, textTransform: "uppercase" }}>{round.name}</h2>
          <p style={{ margin: "2px 0 0", fontSize: 12, color: C.sage, letterSpacing: 1 }}>{round.subtitle} · {round.maxPts} pts</p>
        </div>
        <button onClick={() => setShowAnswers(!showAnswers)} style={{
          ...btnGhost, fontSize: 10,
          color: showAnswers ? C.cream : C.sageDark,
          borderColor: showAnswers ? C.borderMed : C.borderLight,
        }}>
          {showAnswers ? "Hide Answers" : "Show Answers"}
        </button>
      </div>

      {/* Scoring table */}
      <div style={{ padding: "0 12px 100px", overflowX: "auto" }}>
        <table style={{ width: "100%", borderCollapse: "separate", borderSpacing: 0, fontSize: 13 }}>
          <thead>
            <tr>
              <th style={{ ...thStyle, position: "sticky", left: 0, zIndex: 10, minWidth: 120, textAlign: "left", paddingLeft: 12 }}>Team</th>
              {round.questions.map(q => (
                <th key={q.id} style={{ ...thStyle, minWidth: 44 }}>{q.label}</th>
              ))}
              <th style={{ ...thStyle, minWidth: 44, background: C.greenAccent }}>Tot</th>
            </tr>
            {showAnswers && (
              <tr>
                <td style={{ ...ansCell, position: "sticky", left: 0, zIndex: 10, fontWeight: 600, fontSize: 10, textAlign: "left", paddingLeft: 12 }}>Answers</td>
                {round.questions.map(q => (
                  <td key={q.id} style={{ ...ansCell, fontSize: 9, maxWidth: 80, overflow: "hidden", textOverflow: "ellipsis" }} title={q.answer}>{q.answer}</td>
                ))}
                <td style={ansCell}></td>
              </tr>
            )}
          </thead>
          <tbody>
            {activeTeams.map((team, tIdx) => {
              const roundScore = getTeamRoundScore(tIdx, activeRound);
              const bg = tIdx % 2 === 0 ? C.greenDark : C.greenDeep;
              return (
                <tr key={tIdx}>
                  <td style={{ ...tdStyle, position: "sticky", left: 0, zIndex: 5, background: bg, fontWeight: 500, color: C.cream, paddingLeft: 12, textAlign: "left" }}>
                    {team || `Team ${tIdx + 1}`}
                  </td>
                  {round.questions.map(q => {
                    const val = scores[`${tIdx}-${q.id}`];
                    return (
                      <td key={q.id} style={{ ...tdStyle, background: bg, padding: 3 }}>
                        <ScoreButton value={val} onChange={v => setScore(tIdx, q.id, v)} />
                      </td>
                    );
                  })}
                  <td style={{ ...tdStyle, textAlign: "center", fontWeight: 700, fontSize: 15, background: bg, color: roundScore > 0 ? C.creamBright : C.sageDark }}>
                    {roundScore}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}

function ScoreButton({ value, onChange }) {
  const isCorrect = value === 1;
  const isWrong = value === 0;
  return (
    <div style={{ display: "flex", gap: 2, justifyContent: "center" }}>
      <button onClick={() => onChange(1)} style={{
        width: 30, height: 30, borderRadius: 3, border: "none", cursor: "pointer", fontSize: 13, fontWeight: 700,
        background: isCorrect ? C.correct : C.greenMid, color: isCorrect ? C.creamBright : C.sageMuted,
        transition: "all 0.12s", fontFamily: "'Inter', sans-serif",
      }}>✓</button>
      <button onClick={() => onChange(0)} style={{
        width: 30, height: 30, borderRadius: 3, border: "none", cursor: "pointer", fontSize: 13, fontWeight: 700,
        background: isWrong ? C.wrong : C.greenMid, color: isWrong ? C.creamBright : C.sageMuted,
        transition: "all 0.12s", fontFamily: "'Inter', sans-serif",
      }}>✗</button>
    </div>
  );
}

function LeaderboardView({ leaderboard, onBack, revealed, setRevealed, revealCount, setRevealCount, roundsData, roundOrder, sessionCode }) {
  const maxTotal = 67;
  const totalTeams = leaderboard.length;

  const handleRevealNext = () => {
    if (revealCount >= totalTeams) { setRevealed(true); return; }
    setRevealCount(p => p + 1);
  };
  const handleRevealAll = () => { setRevealCount(totalTeams); setRevealed(true); };

  const displayList = revealed
    ? leaderboard
    : [...leaderboard].slice(totalTeams - revealCount).reverse();

  return (
    <div style={{ minHeight: "100vh", background: `url(${HERO_BG}) center/cover no-repeat fixed`, fontFamily: "'Inter', 'Helvetica Neue', sans-serif" }}>
      <div style={{ position: "fixed", inset: 0, background: C.overlay, zIndex: 0 }} />
      <div style={{ position: "relative", zIndex: 1 }}>
        {/* Header */}
        <div style={{ padding: "16px 16px 8px", display: "flex", alignItems: "center", justifyContent: "space-between" }}>
          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            <button onClick={onBack} style={btnGhost}>← Scoring</button>
            <SessionBadge code={sessionCode} />
          </div>
          <div style={{ display: "flex", gap: 8 }}>
            {!revealed && (
              <>
                <button onClick={handleRevealNext} style={btnAccent}>Reveal #{totalTeams - revealCount}</button>
                <button onClick={handleRevealAll} style={btnGhost}>Show All</button>
              </>
            )}
          </div>
        </div>

        {/* Title */}
        <div style={{ textAlign: "center", padding: "8px 16px 28px" }}>
          <LogoMark size="md" />
          <div style={{ marginTop: 24 }}>
            <h1 style={{ fontSize: 18, fontWeight: 300, color: C.cream, margin: 0, letterSpacing: 8, textTransform: "uppercase" }}>Leaderboard</h1>
            <p style={{ color: C.sage, fontSize: 12, margin: "6px 0 0", letterSpacing: 1 }}>
              {revealed ? `${totalTeams} teams · ${maxTotal} points possible` : `${revealCount} of ${totalTeams} revealed`}
            </p>
          </div>
        </div>

        {/* Team cards */}
        <div style={{ maxWidth: 560, margin: "0 auto", padding: "0 16px 40px", display: "flex", flexDirection: "column", gap: 6 }}>
          {displayList.map((team) => {
            const barWidth = maxTotal > 0 ? (team.total / maxTotal) * 100 : 0;
            const isPodium = team.rank <= 3;
            const podiumColor = team.rank === 1 ? C.gold : team.rank === 2 ? C.silver : C.bronze;
            const icons = { 1: "🥇", 2: "🥈", 3: "🥉" };

            return (
              <div key={team.idx} style={{
                background: C.greenDark, borderRadius: 4, padding: "14px 16px",
                border: `1px solid ${isPodium ? podiumColor + "44" : C.borderLight}`,
                boxShadow: isPodium ? `0 0 24px ${podiumColor}18` : "none",
                transition: "all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1)",
                animation: !revealed ? "slideIn 0.4s ease-out" : undefined,
              }}>
                <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
                  <div style={{ width: 36, textAlign: "center", flexShrink: 0 }}>
                    {icons[team.rank] ? (
                      <span style={{ fontSize: 22 }}>{icons[team.rank]}</span>
                    ) : (
                      <span style={{ fontSize: 15, fontWeight: 300, color: C.sage, letterSpacing: 1 }}>#{team.rank}</span>
                    )}
                  </div>

                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ fontWeight: 500, fontSize: 14, color: C.cream, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap", letterSpacing: 0.5 }}>
                      {team.name}
                    </div>
                    <div style={{ marginTop: 6, height: 4, background: C.greenMid, borderRadius: 2, overflow: "hidden" }}>
                      <div style={{
                        width: `${barWidth}%`, height: "100%", borderRadius: 2,
                        background: isPodium ? `linear-gradient(90deg, ${podiumColor}, ${podiumColor}99)` : C.greenSoft,
                        transition: "width 0.6s ease-out",
                      }} />
                    </div>
                    {revealed && (
                      <div style={{ display: "flex", gap: 5, marginTop: 6, flexWrap: "wrap" }}>
                        {roundOrder.map(rid => {
                          const r = roundsData[rid];
                          const s = team.rounds[rid];
                          const lbl = r.type === "series" ? `S${rid.slice(-1)}` : r.type === "varia" ? "V" : "P";
                          return (
                            <span key={rid} style={{
                              fontSize: 9, padding: "1px 5px", borderRadius: 2,
                              background: s > 0 ? "rgba(240,235,224,0.08)" : "transparent",
                              color: s > 0 ? C.sage : C.sageMuted, letterSpacing: 0.5,
                            }}>{lbl}:{s}</span>
                          );
                        })}
                      </div>
                    )}
                  </div>

                  <div style={{ textAlign: "center", flexShrink: 0 }}>
                    <div style={{ fontSize: 24, fontWeight: 300, color: isPodium ? podiumColor : C.cream, lineHeight: 1, letterSpacing: 1 }}>
                      {team.total}
                    </div>
                    <div style={{ fontSize: 9, color: C.sageDark, marginTop: 3, letterSpacing: 1 }}>/{maxTotal}</div>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      <style>{`
        @keyframes slideIn {
          from { opacity: 0; transform: translateY(20px); }
          to { opacity: 1; transform: translateY(0); }
        }
      `}</style>
    </div>
  );
}

